      'faq_3_a': "CP Plus HD 4-કેમેરા સિસ્ટમ ₹18,000–₹28,000 થી શરૂ થાય છે. IP (NVR) સિસ્ટમ ₹35,000–₹55,000 થી શરૂ થાય છે. 4K સિસ્ટમ ₹55,000–₹85,000 થી શરૂ થાય છે. તમામ કિંમતોમાં GST અને ઇન્સ્ટોલેશન શામેલ છે.",
