    "wz_guided_setup_recommended": "வழிகாட்டப்பட்ட அமைப்பு (பரிந்துரைக்கப்படுகிறது)",
    "wz_choose_between_our_easy_guided": "எங்களின் எளிதான வழிகாட்டப்பட்ட அமைப்பு அல்லது கஸ்டம் அமைப்புகளுக்கான அட்வான்ஸ்டு ப்ரோஃபெஷனல் பில்டர் ஆகியவற்றில் ஒன்றைத் தேர்வுசெய்யவும்.",
    "wz_how_would_you_like_to_build_yo": "உங்கள் கொட்டேஷனை எப்படி உருவாக்க விரும்புகிறீர்கள்?",
    "wz_select_the_plan_that_best_fits": "உங்கள் தேவைகளுக்குச் சிறந்த திட்டத்தைத் தேர்ந்தெடுக்கவும் அல்லது விலையை உடனடியாகப் புதுப்பிக்க அமைப்பைப் திருத்தவும்.",
