    "wz_do_you_know_the_technical_spec": "ଆପଣ ଆପଣଙ୍କର ବିଦ୍ୟମାନ ସିଷ୍ଟମ୍‌ର ବୈଷୟିକ ନିର୍ଦ୍ଦିଷ୍ଟତା (ଟେକ୍ନିକାଲ୍ ସ୍ପେସିଫିକେସନ୍) ଜାଣିଛନ୍ତି କି?",
    "wz_i_already_have_a_cctv_system_a": "ମୋ ପାଖରେ ପୂର୍ବରୁ ଏକ CCTV ସିଷ୍ଟମ୍ ଅଛି ଏବଂ ମୁଁ ଆହୁରି ଅଧିକ କ୍ୟାମେରା ଯୋଗ କରିବାକୁ ଚାହୁଁଛି।",
    "wz_add_to_existing_system": "ବିଦ୍ୟମାନ ସିଷ୍ଟମ୍‌ରେ ଯୋଗ କରନ୍ତୁ",
