    "wz_i_already_know_exactly_what_ca": "କେଉଁ କ୍ୟାମେରା ଏବଂ ବୈଷୟିକ ନିର୍ଦ୍ଦିଷ୍ଟତା ଆବଶ୍ୟକ ତାହା ମୁଁ ପୂର୍ବରୁ ଠିକ୍ ଭାବରେ ଜାଣିଛି। ମୋତେ କାଟାଲଗ୍‌ରୁ ମୋର ନିଜସ୍ୱ କଷ୍ଟମ୍ ପ୍ୟାକେଜ୍ ତିଆରି କରିବାକୁ ଦିଅନ୍ତୁ।",
