    "wz_answer_a_few_simple_questions_": "ଆପଣଙ୍କ ସମ୍ପତ୍ତି ବିଷୟରେ କିଛି ସରଳ ପ୍ରଶ୍ନର ଉତ୍ତର ଦିଅନ୍ତୁ, ଏବଂ ଆମର AI ଆପଣଙ୍କ ପାଇଁ ସବୁଠାରୁ ଉପଯୁକ୍ତ ଏବଂ ସୁସଙ୍ଗତ CCTV ପ୍ୟାକେଜ୍ ତୁରନ୍ତ ଗଣନା କରିବ।",
    "wz_guided_setup_recommended": "ଗାଇଡେଡ୍ ସେଟଅପ୍ (ସୁପାରିଶ କରାଯାଇଛି)",
    "wz_choose_between_our_easy_guided": "କଷ୍ଟମ୍ କନଫିଗରେସନ୍ ପାଇଁ ଆମର ସହଜ ଗାଇଡେଡ୍ ସେଟଅପ୍ କିମ୍ବା ଆମର ଆଡଭାନ୍ସଡ୍ ପ୍ରୋଫେସନାଲ୍ ବିଲ୍ଡର୍ ମଧ୍ୟରୁ ବାଛନ୍ତୁ।",
    "wz_how_would_you_like_to_build_yo": "ଆପଣ ନିଜର କୋଟ୍ କିପରି ତିଆରି କରିବାକୁ ଚାହିଁବେ?",
