    "wz_weaposve_received_your_quote_o": "ଆମେ ଆପଣଙ୍କର କୋଟ୍ ପାଇଛୁ। ଆମ ଟିମ୍ ଏହାକୁ ସମୀକ୍ଷା କରିବେ ଏବଂ ଏକ ଗ୍ୟାରେଣ୍ଟିଯୁକ୍ତ ସର୍ବୋତ୍ତମ ମୂଲ୍ୟ ସହିତ 24 ଘଣ୍ଟା ମଧ୍ୟରେ ଆପଣଙ୍କୁ ଯୋଗାଯୋଗ କରିବେ।",
